def classify_slots(raw):
    slots = raw.get('slots')
    valid = (
        type(slots) is list and 1 <= len(slots) <= 4
        and all(type(item) is int and not isinstance(item, bool) and 5 <= item <= 9 for item in slots)
    )
    result = {'ok': valid, 'slots': slots if valid else []}
